// ❌ Tin MỌI response — kể cả response CŨ về SAU
'use client';

export function ProfileEditor() {
  const [bio, setBio] = useState('');
  async function save() {
    const res = await fetch('/api/profile', {
      method: 'PATCH',
      body: JSON.stringify({ bio }),
    });
    const saved = (await res.json()) as { bio: string };
    setBio(saved.bio); // response nào về SAU sẽ ĐÈ lên tất cả
  }
  return (
    <>
      <textarea value={bio} onChange={(e) => setBio(e.target.value)} />
      <button onClick={save}>Lưu hồ sơ</button>
      {/* save#1 (bio cũ) lag 4s · save#2 (bio mới) về sau 1s */}
    </>
  );
}

