// ✅ Request mới HỦY request cũ — hoặc cấm gửi khi đang pending

// 1) AbortController: request cũ bị hủy khi request mới xuất phát
const abortRef = useRef<AbortController | null>(null);

async function save() {
  abortRef.current?.abort();                 // hủy lần đang bay
  const ctrl = new AbortController();
  abortRef.current = ctrl;
  try {
    const res = await fetch('/api/profile', {
      method: 'PATCH',
      body: JSON.stringify({ bio }),
      signal: ctrl.signal,                   // gắn dây hủy
    });
    const saved = (await res.json()) as { bio: string };
    if (!ctrl.signal.aborted) setBio(saved.bio); // chỉ nhận kết quả mới nhất
  } catch (e) {
    if ((e as Error).name !== 'AbortError') toast.error('Lưu thất bại');
  }
}

